  const noText = (re) => (b) => !re.test(b);
  s = nxTplPrune(s, 'div', 'feat', noText(/<h3>[^<]/));
  s = nxTplPrune(s, 'div', 'proc-step', noText(/<h3>[^<]/));
  s = nxTplPrune(s, 'article', 'svc-card', noText(/<h3>[^<]/));
  s = nxTplPrune(s, 'article', 'proj-card', noText(/<h3>[^<]/));
  s = nxTplPrune(s, 'div', 'rev-card', noText(/<p class="rev-text">[^<]/));
  s = nxTplPrune(s, 'div', 'stat-card', (b) => !/\d/.test(((b.match(/<div class="stat-num">([\s\S]*?)<\/div>/) || [])[1] || '').replace(/<[^>]+>/g, '')));
  s = nxTplPrune(s, 'div', 'mini-stat', (b) => !/\d/.test(((b.match(/<div class="n"[^>]*>([\s\S]*?)<\/div>/) || [])[1] || '').replace(/<[^>]+>/g, '')));
