  s = nxTplPrune(s, 'div', 'float-card', noText(/<b>[^<]/));
  s = nxTplPrune(s, 'div', 'hero-photo-cap', noText(/<div class="v">[^<]/));
  s = nxTplPrune(s, 'div', 'info-card', noText(/<b[^>]*>[^<]/));
  s = nxTplPrune(s, 'a', 'info-card', noText(/<b[^>]*>[^<]/));
  s = nxTplPrune(s, 'div', 'why-badge', noText(/<div class="n">[^<]/));
  s = nxTplPrune(s, 'div', 'about-quote', noText(/<p>[^<]/));
  s = nxTplPrune(s, 'div', 'g-score', noText(/<div class="g-num">[^<]/));
  s = nxTplPrune(s, 'div', 'rev-shots', noText(/<img/));
