  const okImg = (u) => /^(https:\/\/[^\s"'<>\\]+|\/[^\s"'<>\\\/][^\s"'<>\\]*|data:image\/(?:png|jpe?g|gif|webp|avif);base64,[A-Za-z0-9+\/=]+)$/i.test(u);
